import React from 'react';
import { ProjectSection, FeatureItem, TechStackItem } from '@/types';

export const createSectionHeader = (
  title: string,
  gradient: string = 'from-blue-500 to-purple-500'
): React.ReactNode => (
  <h4 className="text-2xl md:text-3xl font-bold text-gray-900 flex items-center gap-3 mb-1">
    <span className={`w-1.5 h-7 bg-gradient-to-b ${gradient} rounded-full shadow-sm`}></span>
    <span className="bg-gradient-to-r from-gray-900 via-gray-800 to-gray-900 bg-clip-text text-transparent">
      {title}
    </span>
  </h4>
);

export const createFeatureList = (features: FeatureItem[]): React.ReactNode => (
  <div className="bg-gradient-to-br from-white to-gray-50/50 rounded-2xl p-6 md:p-8 border border-gray-200/60 shadow-lg shadow-gray-200/50 backdrop-blur-sm">
    <div className="grid md:grid-cols-2 gap-4 md:gap-5">
      {features.map((feature, index) => (
        <div key={index} className="flex items-start gap-3 group">
          <div
            className={`w-2.5 h-2.5 rounded-full ${feature.color || 'bg-blue-500'} mt-2 flex-shrink-0 shadow-sm group-hover:scale-125 transition-transform duration-200`}
          ></div>
          <div className="flex-1">
            <strong className="text-gray-900 font-semibold text-base">{feature.title}:</strong>
            <span className="text-gray-600 text-sm leading-relaxed"> {feature.description}</span>
          </div>
        </div>
      ))}
    </div>
  </div>
);

export const createTechStack = (techItems: TechStackItem[]): React.ReactNode => {
  // Map color classes to actual color values for inline styles
  const getColorStyles = (color: string = 'bg-indigo-500') => {
    const colorMap: Record<string, { bgFrom: string; bgTo: string; border: string }> = {
      'bg-indigo-500': { 
        bgFrom: '#e0e7ff', 
        bgTo: '#c7d2fe', 
        border: '#a5b4fc' 
      },
      'bg-blue-500': { 
        bgFrom: '#dbeafe', 
        bgTo: '#bfdbfe', 
        border: '#93c5fd' 
      },
      'bg-green-500': { 
        bgFrom: '#dcfce7', 
        bgTo: '#bbf7d0', 
        border: '#86efac' 
      },
      'bg-purple-500': { 
        bgFrom: '#f3e8ff', 
        bgTo: '#e9d5ff', 
        border: '#d8b4fe' 
      },
      'bg-orange-500': { 
        bgFrom: '#ffedd5', 
        bgTo: '#fed7aa', 
        border: '#fdba74' 
      },
      'bg-pink-500': { 
        bgFrom: '#fce7f3', 
        bgTo: '#fbcfe8', 
        border: '#f9a8d4' 
      },
      'bg-cyan-500': { 
        bgFrom: '#cffafe', 
        bgTo: '#a5f3fc', 
        border: '#67e8f9' 
      },
      'bg-red-500': { 
        bgFrom: '#fee2e2', 
        bgTo: '#fecaca', 
        border: '#fca5a5' 
      },
      'bg-yellow-500': { 
        bgFrom: '#fef9c3', 
        bgTo: '#fef08a', 
        border: '#fde047' 
      },
      'bg-teal-500': { 
        bgFrom: '#ccfbf1', 
        bgTo: '#99f6e4', 
        border: '#5eead4' 
      },
    };
    return colorMap[color] || { bgFrom: '#f3f4f6', bgTo: '#e5e7eb', border: '#d1d5db' };
  };

  return (
    <div className="grid md:grid-cols-2 gap-4 md:gap-5">
      {techItems.map((item, index) => {
        const colors = getColorStyles(item.color);
        return (
          <div 
            key={index} 
            className="flex items-center gap-3 rounded-xl p-4 border-2 shadow-md hover:shadow-lg transition-all duration-200 hover:scale-[1.02]"
            style={{
              background: `linear-gradient(to bottom right, ${colors.bgFrom}, ${colors.bgTo})`,
              borderColor: colors.border,
            }}
          >
            <div className={`w-3 h-3 rounded-full ${item.color || 'bg-indigo-500'} shadow-sm flex-shrink-0 ring-2 ring-white/50`}></div>
            <div className="flex-1">
              <strong className="text-gray-900 font-semibold text-sm">{item.category}:</strong>
              <span className="text-gray-700 text-sm"> {item.technology}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export const createHighlightedSection = (
  title: string,
  content: React.ReactNode,
  gradient: string = 'from-blue-500 to-cyan-500',
  bgColor: string = 'bg-blue-50',
  borderColor: string = 'border-blue-100'
): React.ReactNode => (
  <div className={`space-y-4 ${bgColor} rounded-2xl p-6 md:p-8 border-2 ${borderColor} shadow-lg shadow-blue-100/30 backdrop-blur-sm`}>
    {createSectionHeader(title, gradient)}
    <div className="pt-1">
      {content}
    </div>
  </div>
);

export const createProjectHeader = (
  title: string,
  tags: Array<{ label: string; color?: string }>,
  description: string
): React.ReactNode => (
  <div className="border-b border-gray-200 pb-6">
    <h4 className="text-3xl font-bold text-gray-900 mb-3">
      {title}
    </h4>
    <div className="flex flex-wrap gap-2 text-sm text-gray-600 mb-3">
      {tags.map((tag, index) => (
        <span
          key={index}
          className={`${tag.color || 'bg-blue-100 text-blue-800'} px-2 py-1 rounded font-semibold`}
        >
          {tag.label}
        </span>
      ))}
    </div>
    <p className="text-lg text-gray-600 leading-relaxed">{description}</p>
  </div>
);


